{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Action is the sole human activity that cannot be imagined outside the society of men and depends entirely on the constant presence of others.",
      "claim_type": "author_position",
      "supporting_excerpt": "All human activities are conditioned by the fact that men live together, but it is only action that cannot even be imagined outside the society of men. [...] Action alone is the exclusive prerogative of man; neither a beast nor a god is capable of it, and only action is entirely dependent upon the constant presence of others.",
      "support_kind": "direct",
      "confidence": 1.0
    },
    {
      "claim": "The translation of Aristotle's zōon politikon as animal socialis reflects a loss of the original Greek understanding of politics.",
      "claim_type": "author_position",
      "supporting_excerpt": "This special relationship between action and being together seems fully to justify the early translation of Aristotle’s zōon politikon by animal socialis , already found in Seneca, which then became the standard translation through Thomas Aquinas: homo est naturaliter politicus, id est, socialis (“man is by nature political, that is, social”). More than any elaborate theory, this unconscious substitution of the social for the political betrays the extent to which the original Greek understanding of politics had been lost.",
      "support_kind": "direct",
      "confidence": 1.0
    }
  ],
  "definitions": [
    {
      "term": "bios politikos",
      "definition": "A second life received by man besides his private life upon the rise of the city-state, constituted by action (praxis) and speech (lexis)."
    }
  ],
  "distinctions": [
    {
      "item_a": "What is one's own (idion)",
      "item_b": "What is communal (koinon)",
      "distinction": "A sharp distinction in a citizen's life corresponding to the separation between private life and the second life of the bios politikos."
    }
  ]
}

